-- Release only the DISPUTE gate after reviewed,fully reconciled returned
-- principal. Refund gates and balances remain independent;no history deletion.
CREATE FUNCTION public.provider_dispute_return_eligible(s jsonb,identity_ok boolean,pages_complete boolean) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ BEGIN
 IF identity_ok IS DISTINCT FROM true OR pages_complete IS DISTINCT FROM true OR s IS NULL OR s ? 'unavailable' OR s->'disputeAttentionRetained' IS DISTINCT FROM 'true'::jsonb OR s->'onIsFuture' IS DISTINCT FROM 'false'::jsonb OR s->'onPrecedesCollection' IS DISTINCT FROM 'false'::jsonb
 OR jsonb_typeof(s->'cases') IS DISTINCT FROM 'array' OR jsonb_typeof(s->'movements') IS DISTINCT FROM 'array' OR jsonb_typeof(s->'disputedAssets') IS DISTINCT FROM 'array' OR jsonb_array_length(s->'cases') NOT BETWEEN 1 AND 100 OR jsonb_array_length(s->'movements') NOT BETWEEN 2 AND 200 THEN RETURN false;END IF;
 IF(SELECT count(*)<>count(DISTINCT value->>'disputeId') FROM jsonb_array_elements(s->'cases')) OR(SELECT count(*)<>count(DISTINCT value->>'balanceTransactionId') FROM jsonb_array_elements(s->'movements')) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(s->'cases') c WHERE c->>'status' IS NULL OR c->>'status' NOT IN('won','warning_closed','prevented') OR c->'ownershipConflict' IS DISTINCT FROM 'false'::jsonb OR c->'requiresFxReview' IS DISTINCT FROM 'false'::jsonb OR c->'exceedsOriginalAmount' IS DISTINCT FROM 'false'::jsonb OR c->>'providerUnitScale' IS NULL OR(c->>'amountMinor')::numeric<=0
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'disputedAssets') a WHERE a->>'disputeId'=c->>'disputeId')
 OR coalesce((SELECT sum(-(m->>'grossMinor')::numeric) FROM jsonb_array_elements(s->'movements') m WHERE m->>'disputeId'=c->>'disputeId' AND(m->>'grossMinor')::numeric<0),0)<>(c->>'amountMinor')::numeric
 OR coalesce((SELECT sum((m->>'grossMinor')::numeric) FROM jsonb_array_elements(s->'movements') m WHERE m->>'disputeId'=c->>'disputeId' AND(m->>'grossMinor')::numeric>0),0)<>(c->>'amountMinor')::numeric) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(s->'movements') m LEFT JOIN LATERAL(SELECT value FROM jsonb_array_elements(s->'cases') WHERE value->>'disputeId'=m->>'disputeId') c ON true WHERE c.value IS NULL OR m->'observed' IS DISTINCT FROM 'true'::jsonb OR m->'recognized' IS DISTINCT FROM 'true'::jsonb OR m->'ownershipConflict' IS DISTINCT FROM 'false'::jsonb OR m->'requiresFxReview' IS DISTINCT FROM 'false'::jsonb OR m->'amountMatched' IS DISTINCT FROM 'true'::jsonb OR m->'accountingMatchesLatest' IS DISTINCT FROM 'true'::jsonb OR m->'futureDatedAccounting' IS DISTINCT FROM 'false'::jsonb OR m->>'postingId' IS NULL OR m->'currencyCode' IS DISTINCT FROM c.value->'currencyCode' OR m->'providerUnitScale' IS DISTINCT FROM c.value->'providerUnitScale')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'disputedAssets') a WHERE a->>'balanceMinor' IS NULL OR(a->>'balanceMinor')::numeric<>0) THEN RETURN false;END IF;RETURN true;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN false;
END $$;
CREATE FUNCTION public.provider_dispute_release_basis(p_collection uuid,p_on date) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$
DECLARE c record;principal record;original record;page record;s jsonb;cursor_id text:=NULL;seen uuid[]:=ARRAY[]::uuid[];case_ids text[]:=ARRAY[]::text[];item text;complete boolean:=false;identity_ok boolean;available boolean;history text;books jsonb;stamp text;BEGIN
 SELECT pc.*,cl.time_zone INTO c FROM public.provider_collections pc JOIN public.classes cl ON cl.academy_id=pc.academy_id AND cl.id=pc.class_id WHERE pc.id=p_collection;IF c.id IS NULL THEN RETURN NULL;END IF;
 s=public.provider_dispute_resolution_source(c.id,p_on);IF s IS NULL OR s ? 'unavailable' THEN RETURN jsonb_build_object('eligible',false,'code',coalesce(s->>'unavailable','DISPUTE_RELEASE_SOURCE_UNAVAILABLE'));END IF;
 SELECT * INTO principal FROM public.checkout_provider_inspections WHERE academy_id=c.academy_id AND start_id=c.start_id ORDER BY received_at DESC,id DESC LIMIT 1;SELECT * INTO original FROM public.checkout_provider_inspections WHERE academy_id=c.academy_id AND id=c.inspection_id;
 identity_ok=principal.id IS NOT NULL AND NOT principal.object_conflict AND principal.inspection->'disputed'='false'::jsonb AND(principal.inspection->>'state'='captured' OR(principal.inspection->>'state'='requires_review' AND(principal.inspection->>'refundedAmount')::numeric>0)) AND principal.inspection-ARRAY['state','disputed','paymentVerified','refundedAmount'] IS NOT DISTINCT FROM original.inspection-ARRAY['state','disputed','paymentVerified','refundedAmount'];
 -- A new unrelated refund must not deadlock a previously resolved dispute.
 -- Compare immutable principal identity and dispute facts,not refund counters.
 FOR n IN 1..100 LOOP
  SELECT i.*,p.inspection principal_fact INTO page FROM public.checkout_dispute_inspections i JOIN public.checkout_provider_inspections p ON p.academy_id=i.academy_id AND p.id=i.principal_inspection_id WHERE i.academy_id=c.academy_id AND i.start_id=c.start_id AND i.dispute_inspection->>'state'='dispute_page' AND(i.dispute_inspection->>'startingAfter') IS NOT DISTINCT FROM cursor_id ORDER BY i.received_at DESC,i.id DESC LIMIT 1;
  EXIT WHEN page.id IS NULL OR page.id=ANY(seen) OR page.object_conflict OR page.principal_fact-ARRAY['state','paymentVerified','refundedAmount'] IS DISTINCT FROM principal.inspection-ARRAY['state','paymentVerified','refundedAmount'];seen=array_append(seen,page.id);
  FOR item IN SELECT value->>'id' FROM jsonb_array_elements(page.dispute_inspection->'disputes') LOOP IF item=ANY(case_ids) THEN RETURN jsonb_build_object('eligible',false,'code','DISPUTE_RELEASE_PAGE_CHAIN_CONFLICT');END IF;case_ids=array_append(case_ids,item);END LOOP;
  IF page.dispute_inspection->'hasMore'='false'::jsonb THEN complete=true;EXIT;END IF;cursor_id=page.dispute_inspection->>'nextCursor';
 END LOOP;
 IF NOT public.provider_dispute_return_eligible(s,identity_ok,complete) THEN RETURN jsonb_build_object('eligible',false,'code','DISPUTE_RETURN_RECONCILIATION_REQUIRED');END IF;
 SELECT NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'movements') m JOIN public.checkout_dispute_balance_inspections i ON i.academy_id=c.academy_id AND i.id=(m->>'inspectionId')::uuid WHERE(m->>'grossMinor')::numeric>0 AND i.balance_inspection->>'status' IS DISTINCT FROM 'available') INTO available;
 IF NOT available THEN RETURN jsonb_build_object('eligible',false,'code','DISPUTE_RETURN_BALANCE_NOT_AVAILABLE');END IF;
 WITH facts AS(
  SELECT 'principal'::text stream,i.received_at,i.id,jsonb_build_object('conflict',i.object_conflict,'fact',i.inspection-ARRAY['state','paymentVerified','refundedAmount']) fact FROM public.checkout_provider_inspections i WHERE i.academy_id=c.academy_id AND i.start_id=c.start_id
  UNION ALL SELECT 'page',i.received_at,i.id,jsonb_build_object('conflict',i.object_conflict,'fact',i.dispute_inspection-'principalRequiresReview') FROM public.checkout_dispute_inspections i WHERE i.academy_id=c.academy_id AND i.start_id=c.start_id
  UNION ALL SELECT 'balance:'||(i.balance_inspection->>'balanceTransactionId'),i.received_at,i.id,jsonb_build_object('conflict',i.object_conflict,'fact',i.balance_inspection) FROM public.checkout_dispute_balance_inspections i WHERE i.academy_id=c.academy_id AND i.start_id=c.start_id
 ),changes AS(SELECT *,lag(fact) OVER(PARTITION BY stream ORDER BY received_at,id) prior FROM facts)
 SELECT encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(jsonb_build_array(stream,fact)::text,'UTF8')),'hex'),'' ORDER BY stream,received_at,id) FILTER(WHERE fact IS DISTINCT FROM prior),''),'UTF8')),'hex') INTO history FROM changes;
 SELECT coalesce(jsonb_agg(value ORDER BY family,id),'[]'::jsonb) INTO books FROM(
  SELECT 'posting'::text family,r.id,to_jsonb(r) value FROM public.provider_dispute_postings r WHERE r.academy_id=c.academy_id AND r.collection_id=c.id
  UNION ALL SELECT 'correction',x.id,to_jsonb(x) FROM public.provider_dispute_corrections x JOIN public.provider_dispute_postings r ON r.academy_id=x.academy_id AND r.id=x.posting_id WHERE r.academy_id=c.academy_id AND r.collection_id=c.id
 ) b;
 stamp=encode(sha256(convert_to(jsonb_build_object('version',1,'collectionId',c.id,'on',s->'on','timeZone',c.time_zone,'history',history,'books',books,'cases',(SELECT jsonb_agg(value-'inspectionId' ORDER BY value->>'disputeId') FROM jsonb_array_elements(s->'cases')),'movements',(SELECT jsonb_agg(value-'inspectionId' ORDER BY value->>'disputeId',value->>'balanceTransactionId') FROM jsonb_array_elements(s->'movements')))::text,'UTF8')),'hex');
 RETURN jsonb_build_object('eligible',true,'sourceOn',s->'on','releaseStamp',stamp,'snapshot',s,'refundAttentionRetained',s->'separateRefundAttentionRetained');
END $$;
CREATE TABLE public.provider_dispute_releases(
 academy_id uuid NOT NULL,id uuid NOT NULL,collection_id uuid NOT NULL,source_on date NOT NULL,release_stamp text NOT NULL CHECK(release_stamp~'^[a-f0-9]{64}$'),source jsonb NOT NULL,release_no bigint NOT NULL CHECK(release_no>0),effective_on date NOT NULL,approval_id uuid NOT NULL,created_by uuid NOT NULL,reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(academy_id,id),UNIQUE(academy_id,collection_id,release_stamp),UNIQUE(academy_id,collection_id,release_no),FOREIGN KEY(academy_id,collection_id) REFERENCES public.provider_collections(academy_id,id),FOREIGN KEY(academy_id,approval_id) REFERENCES public.approval_requests(academy_id,id),FOREIGN KEY(academy_id,created_by) REFERENCES public.people(academy_id,id)
);
ALTER TABLE public.provider_dispute_releases ENABLE ROW LEVEL SECURITY;ALTER TABLE public.provider_dispute_releases FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_boundary ON public.provider_dispute_releases USING(academy_id=nullif(current_setting('app.academy_id',true),'')::uuid) WITH CHECK(academy_id=nullif(current_setting('app.academy_id',true),'')::uuid);
CREATE TRIGGER finance_book_write BEFORE INSERT OR UPDATE OR DELETE ON public.provider_dispute_releases FOR EACH STATEMENT EXECUTE FUNCTION public.guard_finance_book_write();
GRANT SELECT,INSERT ON public.provider_dispute_releases TO kavosh_runtime;
CREATE FUNCTION public.provider_dispute_release_current(p_collection uuid,p_on date DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ DECLARE r record;b jsonb;on_day date;BEGIN
 SELECT x.*,cl.time_zone INTO r FROM public.provider_dispute_releases x JOIN public.provider_collections c ON c.academy_id=x.academy_id AND c.id=x.collection_id JOIN public.classes cl ON cl.academy_id=c.academy_id AND cl.id=c.class_id WHERE x.collection_id=p_collection ORDER BY release_no DESC LIMIT 1;IF r.id IS NULL THEN RETURN false;END IF;on_day=coalesce(p_on,(statement_timestamp() AT TIME ZONE r.time_zone)::date);IF on_day<r.effective_on THEN RETURN false;END IF;
 -- ponytail: recheck the bounded native proof,not a stale cached status. A
 -- material source/version counter can replace this only with equivalent
 -- cross-invoice ownership and A->B->A invalidation evidence.
 b=public.provider_dispute_release_basis(r.collection_id,r.source_on);RETURN coalesce(b->'eligible'='true'::jsonb AND b->>'releaseStamp'=r.release_stamp,false);
END $$;
CREATE FUNCTION public.provider_principal_dispute_only(p_collection uuid,p_fact jsonb) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT coalesce(p_fact->'disputed'='true'::jsonb AND p_fact->'refundedAmount'='0'::jsonb AND p_fact-ARRAY['state','disputed','paymentVerified'] IS NOT DISTINCT FROM i.inspection-ARRAY['state','disputed','paymentVerified'],false) FROM public.provider_collections c JOIN public.checkout_provider_inspections i ON i.academy_id=c.academy_id AND i.id=c.inspection_id WHERE c.id=p_collection
$$;
CREATE FUNCTION public.guard_provider_dispute_release() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE c record;p record;b jsonb;BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_RELEASE_IMMUTABLE' USING ERRCODE='23514';END IF;
 SELECT pc.*,cl.time_zone INTO c FROM public.provider_collections pc JOIN public.classes cl ON cl.academy_id=pc.academy_id AND cl.id=pc.class_id WHERE pc.academy_id=NEW.academy_id AND pc.id=NEW.collection_id;
 PERFORM public.lock_customer_credit(c.id);PERFORM public.lock_collector_funds(c.collector_id,c.holding_account);PERFORM id FROM public.tuition_invoices WHERE academy_id=NEW.academy_id AND id=c.invoice_id FOR UPDATE;PERFORM pg_advisory_xact_lock(hashtextextended(NEW.academy_id::text||':checkout-provider:'||c.account_id,0));
 b=public.provider_dispute_release_basis(c.id,NEW.source_on);SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;
 IF b->'eligible' IS DISTINCT FROM 'true'::jsonb OR b IS DISTINCT FROM NEW.source OR b->>'releaseStamp' IS DISTINCT FROM NEW.release_stamp OR p.id IS NULL OR p.action IS DISTINCT FROM 'finance.provider-dispute.release' OR p.status IS DISTINCT FROM 'pending' OR p.target_id IS DISTINCT FROM NEW.id OR p.target_version<>0 OR p.privacy_capability IS DISTINCT FROM 'receipts.edit' OR p.review_context IS DISTINCT FROM jsonb_build_object('releaseStamp',NEW.release_stamp,'sourceOn',NEW.source_on::text,'eligibilityVersion',1)
 OR p.payload IS DISTINCT FROM jsonb_build_object('collectionId',NEW.collection_id,'sourceOn',NEW.source_on::text,'releaseStamp',NEW.release_stamp,'reason',NEW.reason) OR p.scope->'recordContext' IS DISTINCT FROM jsonb_build_object('hubId',c.hub_id,'classId',c.class_id,'studentId',c.student_id) OR NOT public.report_comment_human_verified(NEW.created_by) OR NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND status='active') THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_RELEASE_SOURCE_REQUIRED' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND master_person_id=NEW.created_by) AND(p.requester_id=NEW.created_by OR NOT public.is_supervisor(NEW.created_by,p.requester_id) OR c.student_id=NEW.created_by OR EXISTS(SELECT 1 FROM public.family_relationships WHERE academy_id=NEW.academy_id AND student_id=c.student_id AND guardian_id=NEW.created_by) OR EXISTS(SELECT 1 FROM public.finance_collectors WHERE academy_id=NEW.academy_id AND id=c.collector_id AND person_id=NEW.created_by)) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_RELEASE_UPPER_REQUIRED' USING ERRCODE='23514';END IF;
 SELECT coalesce(max(release_no),0)+1 INTO NEW.release_no FROM public.provider_dispute_releases WHERE academy_id=NEW.academy_id AND collection_id=c.id;NEW.effective_on=(statement_timestamp() AT TIME ZONE c.time_zone)::date;NEW.created_at=clock_timestamp();RETURN NEW;
END $$;
CREATE TRIGGER provider_dispute_release BEFORE INSERT OR UPDATE OR DELETE ON public.provider_dispute_releases FOR EACH ROW EXECUTE FUNCTION public.guard_provider_dispute_release();
CREATE FUNCTION public.complete_provider_dispute_release() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE p record;BEGIN
 SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;
 IF p.status IS DISTINCT FROM 'applied' OR p.reviewer_id IS DISTINCT FROM NEW.created_by OR NEW.source IS DISTINCT FROM public.provider_dispute_release_basis(NEW.collection_id,NEW.source_on) OR NOT EXISTS(SELECT 1 FROM public.audit_events WHERE academy_id=NEW.academy_id AND entity_id=NEW.id AND actor_id=NEW.created_by AND created_at=transaction_timestamp() AND action='finance.provider-dispute.released' AND changes=jsonb_build_object('approvalId',NEW.approval_id,'collectionId',NEW.collection_id,'severity','critical','moneyMovementPerformed',false,'attentionHistoryDeleted',false)) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_RELEASE_INCOMPLETE' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER provider_dispute_release_complete AFTER INSERT ON public.provider_dispute_releases DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.complete_provider_dispute_release();
CREATE FUNCTION public.provider_dispute_release_effect() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF NEW.status='applied' AND NEW.action='finance.provider-dispute.release' AND NOT EXISTS(SELECT 1 FROM public.provider_dispute_releases WHERE academy_id=NEW.academy_id AND id=NEW.target_id AND approval_id=NEW.id AND created_by=NEW.reviewer_id) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_RELEASE_EFFECT_REQUIRED' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER provider_dispute_release_effect AFTER INSERT OR UPDATE ON public.approval_requests DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.provider_dispute_release_effect();
CREATE FUNCTION public.provider_dispute_release_privacy() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE bindings jsonb;BEGIN
 SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]'::jsonb) INTO bindings FROM(SELECT DISTINCT b.value FROM public.approval_requests p CROSS JOIN LATERAL jsonb_array_elements(p.privacy_bindings) b WHERE p.academy_id=NEW.academy_id AND(p.id IN(SELECT approval_id FROM public.provider_dispute_postings WHERE academy_id=NEW.academy_id AND collection_id=(NEW.payload->>'collectionId')::uuid) OR p.id IN(SELECT x.approval_id FROM public.provider_dispute_corrections x JOIN public.provider_dispute_postings d ON d.academy_id=x.academy_id AND d.id=x.posting_id WHERE d.academy_id=NEW.academy_id AND d.collection_id=(NEW.payload->>'collectionId')::uuid))) unique_bindings;
 IF jsonb_array_length(bindings)>60 THEN RAISE EXCEPTION 'DISPUTE_RELEASE_PRIVACY_REQUIRES_BACKGROUND' USING ERRCODE='23514';END IF;NEW.privacy_bindings=NEW.privacy_bindings||bindings;RETURN NEW;
END $$;
CREATE TRIGGER zz_provider_dispute_release_privacy BEFORE INSERT ON public.approval_requests FOR EACH ROW WHEN(NEW.action='finance.provider-dispute.release') EXECUTE FUNCTION public.provider_dispute_release_privacy();
-- Existing native credit/refund gates remain in place. Only covered
-- dispute-only warnings are neutralized;unrelated refund/anomaly facts remain.
DO $$ DECLARE d text;needle text;BEGIN
 d=pg_get_functiondef('public.provider_credit_review_required(uuid,date)'::regprocedure);d=replace(d,'DECLARE c record;','DECLARE release_ok boolean;c record;');needle='IF c.id IS NULL THEN RETURN true;END IF;';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'DISPUTE_RELEASE_CREDIT_BASE_CHANGED';END IF;d=replace(d,needle,needle||'release_ok=public.provider_dispute_release_current(c.id,p_on);');
 needle='IF EXISTS(SELECT 1 FROM public.checkout_dispute_attention da';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'DISPUTE_RELEASE_HOLD_BASE_CHANGED';END IF;d=replace(d,needle,'IF NOT release_ok AND EXISTS(SELECT 1 FROM public.checkout_dispute_attention da');
 needle='bad.inspection->>''state''=''requires_review''';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'DISPUTE_RELEASE_HISTORY_BASE_CHANGED';END IF;EXECUTE replace(d,needle,'(bad.inspection->>''state''=''requires_review'' AND NOT(release_ok AND public.provider_principal_dispute_only(c.id,bad.inspection)))');
 d=pg_get_functiondef('public.provider_credit_review_basis(uuid,uuid[])'::regprocedure);d=replace(d,'DECLARE c record;','DECLARE release_ok boolean;c record;');needle='IF c.id IS NULL THEN RETURN NULL;END IF;';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'DISPUTE_RELEASE_REFUND_BASE_CHANGED';END IF;d=replace(d,needle,needle||'release_ok=public.provider_dispute_release_current(c.id,NULL);');
 d=replace(d,'IF EXISTS(SELECT 1 FROM public.checkout_dispute_attention da','IF NOT release_ok AND EXISTS(SELECT 1 FROM public.checkout_dispute_attention da');needle='bad.inspection->''disputed''=''true''::jsonb';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'DISPUTE_RELEASE_REFUND_HISTORY_CHANGED';END IF;EXECUTE replace(d,needle,'(bad.inspection->''disputed''=''true''::jsonb AND NOT(release_ok AND public.provider_principal_dispute_only(c.id,bad.inspection)))');
END $$;
DO $$ DECLARE d text;needle text;BEGIN
 d=pg_get_functiondef('public.checkout_notice_current(uuid)'::regprocedure);needle='NOT IN(''provider'',''refunds'',''refund_return'')';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'DISPUTE_RELEASE_NOTICE_BASE_CHANGED';END IF;d=replace(d,needle,'NOT IN(''provider'',''refunds'',''refund_return'',''disputes'',''dispute_balance'')');needle='RETURN public.provider_credit_review_required(c);';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'DISPUTE_RELEASE_NOTICE_STATE_CHANGED';END IF;EXECUTE replace(d,needle,'IF e.projection#>>''{attributes,phase}'' IN(''disputes'',''dispute_balance'') THEN RETURN NOT public.provider_dispute_release_current(c);END IF;'||needle);
END $$;
REVOKE ALL ON FUNCTION public.provider_dispute_return_eligible(jsonb,boolean,boolean),public.provider_dispute_release_basis(uuid,date),public.provider_dispute_release_current(uuid,date),public.provider_principal_dispute_only(uuid,jsonb),public.guard_provider_dispute_release(),public.complete_provider_dispute_release(),public.provider_dispute_release_effect(),public.provider_dispute_release_privacy() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.provider_dispute_return_eligible(jsonb,boolean,boolean),public.provider_dispute_release_basis(uuid,date),public.provider_dispute_release_current(uuid,date),public.provider_principal_dispute_only(uuid,jsonb) TO kavosh_runtime;
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 334 $$;
